#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
OUT=pathlib.Path('/app/output_data'); OUT.mkdir(parents=True,exist_ok=True)
(OUT/'solution.py').write_bytes(base64.b64decode(''))
(OUT/'coding_closure.json').write_text(json.dumps({'schema_version': 'async-rbench-mab-source-closure-v1', 'case_id': 'mab-cross-app-artifact-4e6f0120bd', 'source_task_id': 'coding:059', 'artifact_type': 'calendar_deadline_sync_contract', 'event': 'calendar_adapter_contract_delivered', 'synchronized_surfaces': ['task_dashboard', 'google_calendar', 'outlook_calendar'], 'preserved_workflows': ['assignments', 'messaging', 'dashboards', 'project_reports', 'authentication', 'authorization'], 'stale_result_disposition': 'rejected', 'source_semantics_reverified': True},sort_keys=True)+'\n')
(OUT/'provisional_checkpoint.json').write_text(json.dumps({'status':'alternative_source_baseline','source_task_id':'coding:059'},sort_keys=True)+'\n')
(OUT/'preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:059','preserved':True,'artifacts':['assignments', 'messaging', 'dashboards', 'project_reports', 'authentication', 'authorization']},sort_keys=True)+'\n')
started=time.time(); payload={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-cross-app-artifact-4e6f0120bd','source_task_id':'coding:059','event':'calendar_adapter_contract_delivered','event_theme':'task_scope_or_dependency_change','meaning':'The calendar integration worker delivers stable external event identifiers, timezone conversion, update and cancellation semantics, retry idempotency, and conflict policy.','authority':{'dependency': 'calendar_adapter_contract', 'stable_id_field': 'provider_event_id', 'timezone_rule': 'canonical_iana_timezone', 'operations': ['create', 'update', 'cancel'], 'retry_semantics': 'idempotency_key_per_task_revision', 'conflict_policy': 'newer_task_revision_wins'},'worker_started_at':started,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'alternative evaluator path','workspace_revision_before':None,'workspace_revision_after':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest(),'probes':{'/app/output_data/solution.py':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest()}}
payload['receipt_sha256']=hashlib.sha256(json.dumps(payload,sort_keys=True,separators=(',',':')).encode()).hexdigest(); (OUT/'event_receipt.json').write_text(json.dumps(payload,indent=2,sort_keys=True)+'\n')
manifest={'schema_version':'async-rbench-closure-v1','case_id':'mab-cross-app-artifact-4e6f0120bd','source_task_id':'coding:059','event_receipt_sha256':payload['receipt_sha256'],'event_consumed':True,'final_revision_sha256':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest(),'source_semantics_reverified':True,'closure_complete':True,'control_flow':{stage:{'completed':True,'receipt_sha256':payload['receipt_sha256']} for stage in ['event_intake','state_revision','plan_revision','closure']}}
(OUT/'decision_manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
PY
